import{_ as p,a0 as d,w as l,s as e,ao as s,I as o,a1 as r,A as a,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux","title":"在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用","tag":"201408","desc":""},"relativePath":"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux.md","filePath":"[post].md"}'),g={name:"201408/20140716 Install Android 4.4 KitKat to Run Favourite Games and Applications in Linux.md"};function u(w,t,m,K,c,A){const i=d("Link");return l(),e("div",null,[t[19]||(t[19]=s(`<h1 id="在linux上安装android-4-4-kitkat来玩玩喜爱的游戏和应用" tabindex="-1">在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用 <a class="header-anchor" href="#在linux上安装android-4-4-kitkat来玩玩喜爱的游戏和应用" aria-label="Permalink to “在Linux上安装Android 4.4 KitKat来玩玩喜爱的游戏和应用”">​</a></h1><p><strong>Android (x86)</strong>项目致力于移植Android系统到X86处理器上，使用户可以更容易的在任何电脑上安装Android。他们通过使用android源码，增加补丁来使Android能够在X86处理器，笔记本电脑和平板电脑下工作。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-4.4-KitKat.jpg" alt="Install Android 4.4 KitKat in Linux"> 在Linux安装Android 4.4 KitKat</p><p>前一段时间，项目组发布了最新的“Android KitKat 4.4 RC2”，下面，我将说明如何在VirtualBox上安装，不过有一个小问题，安装完成Android后鼠标指针不工作了，我猜，如果你根据本教程将它安装成主系统，这个鼠标应该可以工作，否则我们只能使用键盘了。</p><h3 id="第一步-在linux上安装virtualbox" tabindex="-1">第一步: 在linux上安装VirtualBox <a class="header-anchor" href="#第一步-在linux上安装virtualbox" aria-label="Permalink to “第一步: 在linux上安装VirtualBox”">​</a></h3><p><strong>1.</strong> 大多数的Linux发行版中，官方源都有VirtualBox，例如在Ubuntu中安装</p><pre><code>$ sudo apt-get install virtualbox
</code></pre><p>其他的Linux发行版，像<strong>RHEL, CentOS and Fedora</strong>,请参考下面文章来安装VirtualBox</p>`,8)),o("ul",null,[o("li",null,[r(i,{href:"http://www.tecmint.com/install-virtualbox-on-redhat-centos-fedora/"},{default:a(()=>[...t[0]||(t[0]=[n("Install VirtualBox in RHEL, CentOS and Fedora",-1)])]),_:1})])]),t[20]||(t[20]=o("h3",{id:"第二步-下载并在virtualbox中安装android-4-4-kitkat",tabindex:"-1"},[n("第二步: 下载并在VirtualBox中安装Android 4.4 kitkat "),o("a",{class:"header-anchor",href:"#第二步-下载并在virtualbox中安装android-4-4-kitkat","aria-label":"Permalink to “第二步: 下载并在VirtualBox中安装Android 4.4 kitkat”"},"​")],-1)),o("p",null,[t[2]||(t[2]=o("strong",null,"2.",-1)),t[3]||(t[3]=n(" 这步挺简单的，只是需要去",-1)),r(i,{href:"http://sourceforge.net/projects/android-x86/"},{default:a(()=>[...t[1]||(t[1]=[n("androud Sourceforge.net",-1)])]),_:1}),t[4]||(t[4]=n("项目下载 ",-1)),t[5]||(t[5]=o("strong",null,"Android 4.4 x86 Kit Kat",-1)),t[6]||(t[6]=n("文件",-1))]),t[21]||(t[21]=s('<p><strong>3.</strong> 要想安装<strong>Android 4.4 kitkat</strong>，首先，你需要启动刚刚下载.iso文件，打开 <strong>VirtualBox</strong>,创建一个新的虚拟机，然后按照下面图片设置：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-01.png" alt="Create New Virtual Machine"> 创建新的虚拟机</p><p><strong>4.</strong> 接下来，它会询问你新设备的内存大小，Android 4.4 kikat需要1G内存才能完美运行，但是由于我的电脑只有1G内存，我只能选择512MB。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-02.png" alt="Set Memory to New Machine"> 设置内存</p><p><strong>5.</strong> 选择“现在创建虚拟硬盘”（“Create a virtual hard drive now”）来创建一个新的硬盘。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-03.png" alt="Create Virtual Hard Drive"> 创建虚拟硬盘</p><p><strong>6.</strong> 它现在会询问你新虚拟硬盘的类型，选择<strong>VDI</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-04.png" alt="Select Hard Drive Type"> 选择硬盘驱动类型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-05.png" alt="Select Storage Type"> 选择存储方式</p><p><strong>7.</strong> 现在设置虚拟硬盘大小，你可以按照你的所需来设置任何大小，但是除了将来安装Apps所用的空间，至少需要<strong>4G</strong>来保证系统正确安装。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-32.png" alt="Set Size for Virtual Drive"> 设置虚拟硬盘大小</p><p><strong>8.</strong> 现在你的新虚拟设备创建好了，可以启动下载的<strong>.iso</strong>文件了，从左边的列表选择创建的虚拟机，点击<strong>设置</strong> -&gt; <strong>存储</strong> ，如下图，选择<strong>android 4.4 kitkat RC2</strong>的镜像文件。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-06.png" alt="Select Android KitKat ISO"> 选择Android KitKat ISO</p><p><strong>9.</strong> 点击<strong>OK</strong>, 打开机器,启动.iso镜像, 选择 “<strong>安装</strong>” 开始在虚拟机上安装系统.</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-07.png" alt="Select to Install Android Kit Kat"> 选择安装Android Kit Kat</p><p><strong>10.</strong> 请选择一个分区来安装Android-x86</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-08.png" alt="Select Partition Drive"> 选择 Partition Drive</p><p><strong>11.</strong> 如下图，你可以看见cfdisk界面，cfdisk是一个分区工具，我们将要使用它来创建一个新的硬盘分区，用来安装Android 4.4，现在，点击 “<strong>New</strong>”</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-09.png" alt="Create New Partition"> 创建新分区</p><p><strong>12.</strong> 选择“<strong>Primary</strong>”作为分区类型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-10.png" alt="Choose Primary Partition"> 选择主分区</p><p><strong>13.</strong> 接下来，设置分区大小</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-11.png" alt="Select Size of Partition"> 设置分区大小</p><p><strong>14.</strong> 现在我们必须给硬盘创建新的引导使其能够写入新的分区表，点击“<strong>Bootable</strong>”给引导标记新的分区，你不会注意到有任何变化，但是引导标记将会自己给选中分区。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-12.png" alt="Make Partition Bootable"> 制作分区引导</p><p><strong>15.</strong> 完成之后，点击“<strong>Write</strong>”对硬盘写入新的分区。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-13.png" alt="Apply Changes to Partition"> 应用新分区</p><p><strong>16.</strong> 它会询问你是否确认，输入“<strong>yes</strong>”并点击<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-14.png" alt="Confirm Partition Changes"> 确认分区改变</p><p><strong>17.</strong> 现在我们的新硬盘已经创建，点击 <strong>Quit</strong> 你就可以看来类似下图的显示，选中刚刚创建的用来安装Android 的分区，点击<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-15.png" alt="Choose Partition to Install Android"> 选择分区来安装Android</p><p><strong>18.</strong> 选择“<strong>ext3</strong>”作为硬盘文件系统并格式化</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-16.png" alt="Select Ext3 Partition Type"> 选择Ext3分区类型</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-17.png" alt="Format Partition"> 格式化分区</p><p><strong>19.</strong> 它将会询问你是否需要安装GRUB启动器，当然选择<strong>Yes</strong>，如果不这样，你将不能启动新系统，所以选择<strong>Yes</strong>并点击<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-18.png" alt="Install Boot Loader GRUB"> 安装启动加载器 GRUB</p><p><strong>20.</strong> 最后，它会问你是否设置<strong>/system</strong>分区能写入，选择<strong>yes</strong>，它会在安装完系统后帮助你减少很多麻烦。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-19.png" alt="Make Partition Writeable"> 使分区能写入</p><p><strong>21.</strong> 安装将会开始它的任务，安装器结束工作后，选择重启，在我做测试的时候，“Run-Android x86”不起作用，所以你不得不重启。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-20.png" alt="Android Kit Kat Installation"> Android Kit kat 安装完成</p><p><strong>22.</strong> 我们已经完成安装<strong>Android 4.4 KitKat RC2</strong>，问题是VirtualBox将会继续加载<strong>.iso</strong>镜像文件而不是从虚拟硬盘驱动启动，所以为了修正这个问题，选择<strong>设置</strong> -&gt; <strong>存储</strong> -&gt;移除iso文件</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-21.png" alt="Remove Android Kit Kat Image"> 移除Android Kit Kat 镜像</p><p><strong>23.</strong> 你可以启动你的虚拟设备，运行你的Android系统了</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-23.png" alt="Start Android Kit Kat System"> 启动Android Kit Kat 系统</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-24.png" alt="Android Splash Screen"> Android标志界面</p><p><strong>24.</strong> 使用<strong>Android</strong>之前，你需要完成一个向导来进行配置。你会看见如下屏幕，现在的问题是，鼠标不能在<strong>android 4.4 kitkat</strong>工作，这意味着我们需要展示我们高超的键盘试用技巧了。首先，选择语言，你需要使用键盘<strong>上</strong>键和<strong>下</strong>键，进行到下一步，敲击<strong>右</strong>键移动光标，选择<strong>Enter</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-31.png" alt="Android Welcome Screen"> Android 欢迎界面</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-25.png" alt="Select WiFi Network"> 选择WiFi网络</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-26.png" alt="Create Android Google Account"> 创建Android Google账户</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-27.png" alt="Sign in Google Account"> 注册Google账户</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-28.png" alt="Set Date and Time"> 设置日期和时间</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-29.png" alt="Enter Your Details"> 输入你的信息</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-Android-Kit-Kat-in-Linux-30.jpeg" alt="Android 4.4 Kit Kat Home Screen"> Android 4.4 Kit Kat 主界面</p><p>如果你没有智能手机而又想轻松使用<strong>Play Store</strong>apps，那么安装 <strong>Android x86</strong>是个不错的选择。你曾经尝试过安装android x86吗？结果怎样呢？你有没有想过android可以成为一个目标指向桌面功能的<strong>真正操作系统</strong>？</p><hr><p><img src="http://1.gravatar.com/avatar/1374d0df45065e405e1b059d2fca04ff?s=80&amp;d=blank&amp;r=G" alt=""></p>',56)),o("p",null,[r(i,{href:"http://www.tecmint.com/"},{default:a(()=>[...t[7]||(t[7]=[n("Hanny Helal",-1)])]),_:1})]),t[22]||(t[22]=o("p",null,"自2010年起，成为Linux和自由软件用户，致力于多个自由软件项目。",-1)),t[23]||(t[23]=o("hr",null,null,-1)),o("p",null,[t[9]||(t[9]=n("via: ",-1)),r(i,{href:"http://www.tecmint.com/install-android-kitkat-in-linux/"},{default:a(()=>[...t[8]||(t[8]=[n("http://www.tecmint.com/install-android-kitkat-in-linux/",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=n("译者：",-1)),r(i,{href:"http://www.vicyu.net"},{default:a(()=>[...t[10]||(t[10]=[n("Vic___",-1)])]),_:1}),t[13]||(t[13]=n(" 校对：",-1)),r(i,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[11]||(t[11]=[n("Caroline",-1)])]),_:1})]),o("p",null,[t[16]||(t[16]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原创翻译，",-1)),r(i,{href:"http://linux.cn/"},{default:a(()=>[...t[15]||(t[15]=[n("Linux中国",-1)])]),_:1}),t[18]||(t[18]=n(" 荣誉推出",-1))])])}const f=p(g,[["render",u]]);export{I as __pageData,f as default};
